INSERT INTO galleries (id, title, image_path, description, created_at, updated_at) VALUES
(1, 'First Annual Postal and Courier Baraza', 'gallery/rvnDVhAjL3OkVnXzlWiSLFmdVVrKNpT3CN0y0f1m.jpg', 'CONSENT staff showcased IEC materials on consumer rights and responsibilities during the 1st Annual Postal and Courier Baraza held on April 24, 2025, at Kampala Railway Grounds.', '2025-04-28 07:34:02', '2025-04-28 07:34:02'),
(2, 'The State Minister responsible for Animal Husbandry, Hon. Bright Rwamirama launching the report on Aflatoxin In Uganda', 'gallery/1qP6o8PHLRnJiVYj9xnEEG7vAGfxxURncjt6j5tt.jpg', 'High-level breakfast meeting ahead of the World Food Safety Day celebrations hosted by the National Agricultural Research Orgnisation (NARO) in partnership with CONSENT and Food and Agriculture Organization on 4th June 2025 at Hotel Africana, Kampala.', '2025-06-05 06:51:25', '2025-06-05 06:51:25'),
(3, 'High Level Breakfast on Aflatoxin Control and Food Safety', 'gallery/RPn3oukCuFAiYSiflGeYA5EiXudu0eakhEEh9jb2.jpg', 'Participants pose for a group photo after the high-level breakfast meeting on Aflatoxin Control and Food Safety, hosted by the National Agricultural Research Organization (NARO) in collaboration with CONSENT and the Food and Agriculture Organization (FAO). The event, held on June 4, 2025, at Hotel Africana in Kampala, also marked the official launch of the Aflatoxin Report for Uganda.', '2025-06-05 08:04:21', '2025-06-05 08:04:21'),
(4, 'World Food Safety Day', 'gallery/A77rkZGShCvMcBjLUnPUBwLFzxwK43RLc2eBsPi0.jpg', 'The National Agricultural Research Organisation (NARO), in partnership with several Civil Society Organisations, addresses the press during the World Food Safety Day celebration at City Square, Kampala.', '2025-06-09 10:32:26', '2025-06-09 10:32:26'),
(5, 'World Food Safety Day Celebration', 'gallery/JetwzRDzmpwZIzbjCvSTLnWXJFXkfphft5IivZTV.jpg', 'Mr. Kimera Henry, Team Leader at CONSENT, participates in the Food Safety Walk held in commemoration of World Food Safety Day on 7th June 2025.', '2025-06-09 11:18:19', '2025-06-09 11:18:19'),
(6, 'World Food Safety Day', 'gallery/Co2yaeiyXp8DorBaj7BdN3W6EQbEk4Zuq7W3i2Zp.jpg', 'The National Agricultural Research Organisation, in partnership with several Civil Society Organisations, participated in the World Food Safety Day celebration on 7th June 2025 at City Square, Kampala, to raise awareness about aflatoxins.', '2025-06-09 11:36:29', '2025-06-09 11:36:29'),
(7, 'World Food Safety Day', 'gallery/MLIawTK3bPDUGUyhkOkRMx9AxqGfudzXfIvsUhnJ.jpg', 'Uganda commemorated World Food Safety Day on 7th June 2025 with a 5km awareness walk to highlight the dangers of aflatoxins', '2025-06-09 11:51:32', '2025-06-09 11:51:32'),
(8, 'From left to right: Mr. Kizito Elvis (UPA-FNS), Ms. Doreen Akwera (Cefroht), Ms. Nyapendi Janet (KeBERA Organics), and Ms. Ashah Ntabadde (CONSENT) pose for a photo at the Uganda AgriFood Systems Investment and Financing Summit.', 'gallery/B7NsmFdSW8XDMJpGl3pDnqe7bmJsrAOUznLWF7QW.jpg', 'Uganda Agri-food Investment and Financing Conference was led by the Food and Agriculture Organization (FAO), the Office of the Prime Minister (OPM), and the Ministry of Agriculture, Animal Industry and Fisheries (MAAIF), under the background to catalyze the shift by promoting systems investing as a central pillar of food systems transformation. By aligning financial flows with a shared vision of systemic change under NDP IV', '2025-06-26 21:39:41', '2025-06-26 21:49:53'),
(9, 'Group photo moment with participants from the legal fraternity, academia, civil society organizations, and UNCC partner members during the training held on 18th July 2025 at Kampala Serena Hotel.', 'gallery/YSdLzxzu9dYIya9SZxGNCwsrOSVrqbvB0Cc7YMjw.jpg', 'The legal fraternity, academia, civil society organizations, and Uganda National Civil Society Coalition (UNCC) partner members participated in a training held on 18th July 2025 at the Kampala Serena Hotel. The training aimed to engage lawyers in discussions and capacity building around emerging frontiers of legal practice related to non-communicable diseases (NCDs), food systems, and intellectual property in the pharmaceutical sector.', '2025-07-21 12:05:41', '2025-07-21 12:05:41'),
(10, 'Lauch of The Agroecology Legal Network for Africa (ALENAF)', 'gallery/W70WF6bI1kgbldASZ0VzxWeEwk3rmv2Xk1lyy61f.jpg', 'Prof. Ben Twinomugisha, health and human rights activist, officially launched the Agroecology Legal Network for Africa, a new legal hub supporting the agroecology movement, on behalf of the Centre for Food and Adequate Living Rights, (CEFROHT).  On 18th July 2025, at Kampala Serena Hotel', '2025-07-21 13:42:15', '2025-07-21 13:42:15'),
(11, 'Press Conference on unprocessed foods and rising NCDs in Uganda', 'gallery/ZOWFFF5z3yWxcS8gWmHb2jochk5y7DXyNcktKcjr.png', 'A press conference held by the Uganda National CSO Coalition-Front of Pack Warning Labelling at Piato Restaurant in Kampala. Organized by the Centre for Food and Adequate Living Rights (CEFROHT) to address the issues of unprocessed foods and the rising rates of non-communicable diseases (NCDs) in Uganda. The conference focused on evidence-based nutrition, media accountability, and the urgent need to adopt Uganda''s Nutrition Profiling Model (NPM). A joint resolution was made, calling for the Ministry of Health to immediately sign the draft NPM, regulate misleading nutritional claims in the media, and support public education on healthy indigenous diets.', '2025-08-06 23:01:42', '2025-08-06 23:01:42'),
(12, 'A group photo with the UNCC members and the GHAI team on 28th August.', 'gallery/tKWPC0hSXo5Al9GU1vYgENQjhDZtK2q1RvzAvqvc.jpg', 'The Uganda National Civil Society Coalition (UNCC) on a two-day engagement with Bloomberge and the Global Health Incubator team; this engagement meant to share UNCC work with the program donors and forge ahead to the next batch of funding; the engagement also involved visiting different actors like the Ministry of Health, National Planning Authority, the Ministry of Justice, and academic institutions among others.', '2025-08-28 23:41:05', '2025-08-28 23:41:05'),
(13, 'Photo Moment after the Food and Nutrition Landscape in Uganda Multi-stakeholder Policy Dialogue', 'gallery/9H14o2IVUloTx6RJcoOvHyD15mbXlQnW4bhi8OQu.jpg', 'The Food and Nutrition Landscape in Uganda Multi-stakeholder Policy Dialogue - Unpacking the Progress of the Food & Nutrition Bill 2024 and strategies to curb Unhealthy Diets through Nutrient Profiling. The objectives of the engagement were to assess the comprehensiveness of the Bill towards effective regulation of the food environment and its progress to becoming an Act.', '2025-09-04 01:18:53', '2025-09-04 01:18:53'),
(14, '"Beera Ku Guard" Campaign', 'gallery/WHQOSWiK23THI4ZfdmcEHJ7Rrrb9Zucpu4AaxTFX.jpg', 'Mr Henry Kimera, Team Leader CONSENT, joined NITA-U at the media launch of the nationwide digital cybersecurity, data protection, and privacy awareness campaign at Serana Kampala Hotel.', '2025-09-04 01:25:41', '2025-09-04 01:25:41');
